-- The append-only log (02-architecture/event-log.md).
--
-- Generated by `drizzle-kit generate` from drizzle/schema.ts, then extended
-- with the two triggers below, which are hand-written because they are the
-- invariant rather than a shape.
--
-- **Every statement is `IF NOT EXISTS`, and it has to be.** The client applies
-- this file when it opens the local database, which happens on every launch
-- rather than once — there is no migrator in a browser, because `drizzle-kit`'s
-- reads a folder with `fs`. Without the guards the second launch throws
-- "table log_entries already exists" and the app quietly falls back to
-- "nothing can be stored here".
--
-- This is enough while every migration only creates. **The first migration that
-- alters or drops needs a tracked migrator** (a `migrations` table plus an
-- ordered list of applied tags), and that is the point at which this comment
-- stops being an excuse.

CREATE TABLE IF NOT EXISTS `log_entries` (
	`id` text PRIMARY KEY NOT NULL,
	`type` text NOT NULL,
	`timestamp` text NOT NULL,
	`actor_type` text NOT NULL,
	`actor_id` text,
	`payload` text NOT NULL,
	`compensation_for` text,
	`schema_version` integer NOT NULL,
	`device_id` text NOT NULL,
	`seq` integer NOT NULL,
	`sync` integer DEFAULT true NOT NULL
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `log_entries_order_idx` ON `log_entries` (`timestamp`,`device_id`,`seq`);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `log_entries_device_seq_idx` ON `log_entries` (`device_id`,`seq`);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `log_entries_type_idx` ON `log_entries` (`type`);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `log_entries_compensation_idx` ON `log_entries` (`compensation_for`);
--> statement-breakpoint
-- "The log is append-only. Log entries are never mutated and never deleted."
-- Making that a trigger rather than a convention is the same move
-- `02-architecture/projections.md` makes for protocol immutability: a bug or a
-- sync from another device cannot do the forbidden thing either.
--
-- A deliberate local-data reset would have to drop these first. That is a
-- decision the docs have not made, which is exactly why it should be loud.
CREATE TRIGGER IF NOT EXISTS `log_entries_no_update`
BEFORE UPDATE ON `log_entries`
BEGIN
	SELECT RAISE(ABORT, 'the log is append-only: entries are never mutated');
END;
--> statement-breakpoint
CREATE TRIGGER IF NOT EXISTS `log_entries_no_delete`
BEFORE DELETE ON `log_entries`
BEGIN
	SELECT RAISE(ABORT, 'the log is append-only: entries are never deleted');
END;
